guQ(){return"\u0baa\u0b9e\u0bcd\u0b9a\u0bcd \u0ba4\u0b95\u0bb5\u0bb2\u0bcd"},
guf(){return"\u0bae\u0bc1\u0b95\u0bae\u0bcd \u0baa\u0bca\u0bb0\u0bc1\u0ba8\u0bcd\u0ba4\u0bbf\u0baf\u0ba4\u0bc1"},
